const tradeExam: ExamQuestion = {
  id:'trade-guided-exam',title:'Comparative advantage, tariff and exchange',ref:'14',
  note:'Mini-examen pédagogique construit sur E2020–E2025 et §14. Les nombres de commerce et de tarif sont documentés/recalculés ; l’échange 3 drinks contre 2 snacks est construit. Fondé sur le cours L13 ; cette réponse n’est pas officielle.',
  statement:'North needs 3 hours per wheat unit and 6 per electronics unit; South needs 4 and 2 respectively. A separate small importing country has domestic inverse demand 80−Q, inverse supply 20+Q and world price 30. A tariff of 10 is introduced. Finally, Christina and Sebastian each own 10 drinks and 10 snacks; U_C=D_C+S_C and U_S=D_S+2 S_S.',
  parts:[
    {kind:'num',id:'trade',prompt:'Calculate the opportunity cost of wheat in electronics for each country.',answers:[{label:'North E per W',value:0.5},{label:'South E per W',value:2}],explain:'Divide hours per wheat by hours per electronics:3/6=0,5;4/2=2. North has comparative advantage in wheat.',tags:['trade']},
    {kind:'num',id:'tariff',prompt:'After the tariff, find domestic price, imports, tariff revenue and national deadweight loss.',answers:[{label:'Domestic price',value:40},{label:'Imports',value:20},{label:'Tariff revenue',value:200},{label:'DWL',value:100}],explain:'Price 30+10=40; Q_D40,Q_S20,M20; revenue 10×20=200; DWL0,5×10×(10+10)=100.',tags:['trade']},
    {kind:'num',id:'exchange',prompt:'Sebastian gives 3 drinks and receives 2 snacks. Find both final utilities.',answers:[{label:'Sebastian',value:31},{label:'Christina',value:21}],explain:'Sebastian (7,12): 7+24 = 31; Christina (13,8): 13+8 = 21. Totals remain 20/20.',tags:['trade']},
    {kind:'text',id:'explain-rule',prompt:'Explain who gains and who loses from the tariff, and why the Pareto-improving exchange need not yet be Pareto efficient.',rubric:[r('groups','Consumers lose, producers and government gain',/consumer/i,/producer|government|revenue/i),r('dwl','Net national loss',/deadweight|net loss|dwl/i),r('further','Further feasible gains from exchange',/further|still|more/i,/drink|snack|trade|exchange/i)],model:'The tariff raises the domestic price to 40: consumers lose surplus, domestic producers gain and the government collects 200, but the net national loss is 100 because extra domestic production costs more than the world price and some valuable consumption disappears. The exchange raises both utilities, so it is a Pareto improvement, but Sebastian still has drinks and Christina still has snacks. Their different marginal valuations allow further mutually beneficial trade, so the allocation is not yet Pareto efficient.',tags:['trade']},
  ],
  logic:['Convert input requirements into opportunity costs with units.','For the small country, verify imports remain positive before using p_w+τ.','Keep transfers within national welfare and calculate both distortion triangles.','For exchange, check both utilities, feasibility and whether further gains remain.'],
  calc:['OC_W North=3/6=0,5 E; South=4/2=2 E.','Before tariff:QD50,QS10,M40. After:QD40,QS20,M20.','ΔCS−450+ΔPS150+revenue200=−100.','Exchange: U_S7+2×12=31; U_C13+8=21.'],
  graph:['PPF: wheat horizontal, electronics vertical; slopes−0,5 and−2, with production constrained by available hours.','Tariff: draw world price 30 and domestic 40, then read the horizontal demand-supply gaps.','Edgeworth: fixed totals 20×20, opposite origins, initial allocation 10/10; with perfect substitutes efficient allocations lie on relevant boundaries.'],
  modelAnswer:'North has comparative advantage in wheat because its opportunity cost is 0.5 electronics rather than 2. The tariff raises domestic price to 40, reduces imports to 20 and yields revenue 200, but causes a national welfare loss 100. The exchange gives Sebastian utility 31 and Christina 21, a Pareto improvement. It is not yet efficient because further mutually beneficial transfers of snacks to Sebastian for drinks are feasible.',
};
const complementExam: ExamQuestion = {
  id:'complements-guided-exam',title:'Read the rule before calculating',ref:'14',
  note:'Mini-examen pédagogique construit sur E2022, E2023, E2025 et §14. Les nombres d’enchères sont documentés/recalculés. Fondé sur le cours L14 ; cette réponse n’est pas officielle.',
  statement:'Three bidders value an object at 80, 100 and 92 million (private values). A platform connects buyers and sellers; buyers have very elastic demand and each buyer creates a large benefit for sellers.',
  parts:[
    {kind:'num',id:'auction',prompt:'Assuming truthful bids in a second-price sealed-bid auction, find the payment and winner’s surplus.',answers:[{label:'Payment (million)',value:92},{label:'Winner surplus (million)',value:8}],explain:'The bidder with value 100 wins, pays the second-highest bid 92 and receives surplus 8.',tags:['complements']},
    {kind:'num',id:'english',prompt:'In an English auction with reserve price 50, at about which price does bidding stop?',answers:[{label:'Price (million)',value:92}],explain:'The bidder with value 92 drops out at 92; the bidder with value 100 wins at about 92, as in the Vickrey auction.',tags:['complements']},
    {kind:'choice',id:'fees',prompt:'Which fee structure should the platform choose?',tags:['complements'],options:[{text:'Low fee or subsidy for buyers, higher fee for sellers',correct:true,feedback:'Buyers are elastic and create value for sellers: both forces lower their price.'},{text:'Equal fees on both sides',feedback:'Nothing requires symmetry: elasticities and cross-side benefits differ.'},{text:'High fee for buyers because they gain most',feedback:'High fees would drive away the elastic side and the value it brings to sellers.'}]},
    {kind:'text',id:'explain-rule',prompt:'Explain why truthful bidding is not a universal auction rule and why network effects alone do not prove that one platform will dominate.',rubric:[r('payment','Second-price payment fixed by rivals',/second.?price|second.highest/i,/rival|other|payment|pays/i),r('limit','Other auction rules change incentives',/first.?price|own bid|common value/i),r('homing','Multi-homing or congestion allows coexistence',/multi.?homing|congestion|weak network|several platforms/i)],model:'Truthful bidding is weakly dominant under the private-value second-price rule because the winner’s payment is set by the other bids. The same argument does not apply to a first-price auction, where the bid is the payment, or automatically to common values. Network effects push towards concentration, but multi-homing, congestion and weak network effects allow several platforms to coexist, so dominance is not automatic.',tags:['complements']},
  ],
  logic:['Read the auction payment rule; then compare value to payment.','Static or dynamic, first or second price: classify the auction before solving it.','For a platform, name both sides, their elasticities and the benefit each creates for the other.','List forces for concentration and for coexistence before concluding.'],
  calc:['Vickrey: winner value 100 − payment 92 = 8.','English: bidding stops at the second value, 92.'],
  graph:['No figure is required; a 2×2 table of auction formats (static/dynamic × first/second price) helps.'],
  modelAnswer:'In the second-price sale, the bidder with value 100 wins and pays 92, earning 8; an English auction stops at about the same price. Truthful bidding cannot be transferred mechanically to first-price or common-value auctions. The platform should charge buyers little or subsidise them, because they are price-sensitive and create value for sellers, and recover revenue from sellers. Network effects alone do not prove dominance when users multi-home or when congestion limits the largest platform.',
};
